package pl.dyktafon;
import java.nio.*;import java.nio.file.*;import java.util.*;
public class T{static int SENS=5;static double[] run(double[] y,boolean[] ws,int F,double[] prof){double[] o=y.clone();Denoiser d=new Denoiser(F,prof);Vad v=new Vad(F/8);for(int i=0,k=0;i+F<=o.length;i+=F,k++){double[] f=Arrays.copyOfRange(o,i,i+F);d.process(f,F);System.arraycopy(f,0,o,i,F);ws[k]=v.update(d.takeBandDb(),SENS,1.0);}return o;}
public static void main(String[] a)throws Exception{if(a.length>1)SENS=Integer.parseInt(a[1]);byte[] b=Files.readAllBytes(Paths.get(a[0]));int n=b.length/2;double[] s=new double[n];ByteBuffer B=ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<n;i++)s[i]=B.getShort()*0.5;
Random R=new Random(1);int pad=8000*4;double[] x=new double[n+2*pad];System.arraycopy(s,0,x,pad,n);double sp=0;for(double v:s)sp+=v*v;sp/=n;
String[] kinds={"white","low-frequency hum/rumble","fluctuating room noise"};for(int L:new int[]{1,20}){for(int i=0;i<n;i++)x[pad+i]=s[i]/L;sp=0;for(double v:s)sp+=v*v/(L*L);sp/=n;System.out.println("== speech scale 1/"+L);
for(int kind=0;kind<3;kind++){System.out.println("-- "+kinds[kind]);for(double snr:new double[]{10,5,0,-5}){for(int ps=0;ps<1;ps++){double nv=Math.sqrt(sp/Math.pow(10,snr/10));double[] w=new double[x.length];double lp=0;for(int i=0;i<w.length;i++){double g=R.nextGaussian();if(kind==0)w[i]=g;else if(kind==1){lp=.9*lp+.1*g;w[i]=lp*3.2;}else{lp=.9*lp+.1*g;w[i]=(lp*2.2+.5*g)*(1+.5*Math.sin(i*2*Math.PI*.7/8000)+.25*Math.sin(i*2*Math.PI*3.1/8000));}}
 double[] y=new double[x.length];for(int i=0;i<y.length;i++)y[i]=x[i]+nv*w[i];
 double[] prof=null;if(ps==1){double[] tmp=new double[8000*2];double l2=0;for(int i=0;i<tmp.length;i++){double g=R.nextGaussian();if(kind==0)tmp[i]=nv*g;else{l2=.9*l2+.1*g;tmp[i]=nv*l2*3.2;}}Denoiser d=new Denoiser(320,null);d.startSample(1.9);for(int i=0;i+320<=tmp.length;i+=320){double[] f=Arrays.copyOfRange(tmp,i,i+320);d.process(f,320);}prof=d.profile();}
 boolean[] ws=new boolean[y.length/320+1];double[] o=run(y,ws,320,prof);
 double best=-99;for(int lag=0;lag<=600;lag+=8){double ep=0,np=0;for(int i=pad;i<pad+n;i++){double e=o[i+lag]-x[i];ep+=e*e;np+=x[i]*x[i];}best=Math.max(best,10*Math.log10(np/ep));}
 double inN=0,outN=0;for(int i=pad-16000;i<pad-1000;i++){inN+=y[i]*y[i];outN+=o[i]*o[i];}
 int onS=0,cS=0,onN=0,cN=0;for(int k=0;k<ws.length-1;k++){int i=k*320;if(i>=pad&&i<pad+n){cS++;if(ws[k])onS++;}else if(i>pad+n+16000||(i<pad-1000&&i>16000)){cN++;if(ws[k])onN++;}}
 System.out.printf("in %3.0f dB %s: out %5.1f dB, silence noise -%4.1f dB, VAD on speech %3.0f%%, on noise %2.0f%%%n",snr,ps==1?"sample":"auto  ",best,10*Math.log10(inN/outN),100.0*onS/cS,100.0*onN/cN);}}}}}}